_W = None
def _decode_w(b64):
    return pickle.loads(gzip.decompress(base64.b64decode(b64.strip())))
_W_2P = _decode_w(_W_B64_2P)   # 2-player: v3 final (ckpt_tf3, waste-shaped)
_W_4P = _decode_w(_W_B64_4P)   # 4-player: ckpt_tf3_4p
_W = _W_2P                     # selecionado por n_players em agent()

# --------------------------------------------------------------------------- #
P_MAX = 48; CENTER = 50.0; SUN_R = 10.0; ROT_LIMIT = 50.0; MAX_SPEED = 6.0
LOG1000 = math.log(1000.0); GARRISON = 1.0; MAX_DIST = 60.0; MARGIN = 1.1
SUN_BUF = 2.0; BOARD = 100.0; LAUNCH_CLEAR = 0.1; SWEPT_BUFFER = 4
FRAC_BINS = np.array([0.25, 0.5, 0.75, 1.0])

def _relu(x): return np.maximum(x, 0.0)
def _lin(x, name): return x @ _W[f"params/{name}/kernel"] + _W[f"params/{name}/bias"]

def _speed(ships):
    s = np.clip(np.log(np.maximum(ships, 1.0)) / LOG1000, 0.0, 1.0)
    return np.minimum(1.0 + (MAX_SPEED - 1.0) * s**1.5, MAX_SPEED)

def _seg_dist_center(ax, ay, bx, by):
    vx, vy = bx - ax, by - ay; l2 = vx*vx + vy*vy
    t = ((CENTER-ax)*vx + (CENTER-ay)*vy) / np.where(l2 == 0, 1.0, l2)
    t = np.where(l2 == 0, 0.0, np.clip(t, 0.0, 1.0))
    return np.hypot(CENTER - (ax + t*vx), CENTER - (ay + t*vy))

def _seg_dist_center_s(ax, ay, bx, by):
    vx, vy = bx - ax, by - ay; l2 = vx*vx + vy*vy
    if l2 == 0.0: return math.hypot(CENTER - ax, CENTER - ay)
    t = max(0.0, min(1.0, ((CENTER-ax)*vx + (CENTER-ay)*vy) / l2))
    return math.hypot(CENTER - (ax + t*vx), CENTER - (ay + t*vy))

def _ships_needed(tships, tprod, towner, dist):
    produces = (towner != -1).astype(float); guess = tships + 1.0
    for _ in range(2):
        eta = dist / _speed(guess); defenders = tships + produces * tprod * eta
        guess = defenders + 1.0
    return np.ceil((defenders + 1.0) * MARGIN)

# --------------------------------------------------------------------------- #
def _theta(n_players, me):
    if n_players <= 2:
        return math.pi if me == 1 else 0.0
    return {0: 0.0, 1: math.pi / 2, 2: 3 * math.pi / 2, 3: math.pi}.get(me, 0.0)

def _parse_obs(obs, me=0, theta=0.0):
    planets = obs["planets"]
    omega = float(obs.get("angular_velocity", 0.03)); step_n = int(obs.get("step", 0))
    pv = np.zeros(P_MAX, bool); po = np.full(P_MAX, -1, np.int32)
    px = np.zeros(P_MAX); py = np.zeros(P_MAX); pr = np.zeros(P_MAX)
    ps = np.zeros(P_MAX); pp = np.zeros(P_MAX); porb = np.zeros(P_MAX, bool)
    iscm = np.zeros(P_MAX, bool); comet_ids = set(obs.get("comet_planet_ids", []))
    ca, sa = math.cos(-theta), math.sin(-theta)
    for i, pl in enumerate(planets[:P_MAX]):
        _id, owner, x, y, r, ships, prod = pl
        pv[i] = True
        po[i] = -1 if (owner is None or owner == -1) else (0 if owner == me else 1)
        if theta != 0.0:
            dx, dy = x - CENTER, y - CENTER
            x = CENTER + dx*ca - dy*sa; y = CENTER + dx*sa + dy*ca
        px[i] = x; py[i] = y; pr[i] = r; ps[i] = ships; pp[i] = prod
        porb[i] = (math.hypot(x-CENTER, y-CENTER) + r) < ROT_LIMIT
        iscm[i] = _id in comet_ids
    # frotas em voo (p/ as features inbound do v3): rotacionadas p/ a perspectiva
    fleets = obs.get("fleets", []) if hasattr(obs, "get") else getattr(obs, "fleets", [])
    fleets = fleets or []
    nf = len(fleets)
    fox = np.zeros(nf); foy = np.zeros(nf); foa = np.zeros(nf)
    fown = np.zeros(nf, np.int32); fsh = np.zeros(nf)
    for i, fl in enumerate(fleets):
        _fid, fo_, fx_, fy_, fang_, _from, fships = fl
        if theta != 0.0:
            dx, dy = fx_ - CENTER, fy_ - CENTER
            fx_ = CENTER + dx*ca - dy*sa; fy_ = CENTER + dx*sa + dy*ca
            fang_ = fang_ - theta
        fox[i] = fx_; foy[i] = fy_; foa[i] = fang_
        fown[i] = 0 if fo_ == me else 1; fsh[i] = fships
    return dict(pv=pv, po=po, px=px, py=py, pr=pr, ps=ps, pp=pp, is_comet=iscm,
                porb=porb, omega=omega, step=step_n, planets=planets, theta=theta,
                fx=fox, fy=foy, fang=foa, fown=fown, fsh=fsh)

# ---- features (14 por planeta) + pair (3) + globais (6) -------------------- #
def _features14(st):
    po, px, py = st["po"], st["px"], st["py"]; ps, pp, pv = st["ps"], st["pp"], st["pv"]
    porb = st["porb"]; mine = (po == 0) & pv; enemy = (po == 1) & pv; neutral = (po == -1) & pv
    rentab = pp / (ps + 1.0)
    dij = np.hypot(px[:, None]-px[None, :], py[:, None]-py[None, :])
    dist_enemy = np.where(enemy[None, :], dij, 1e9).min(1)
    dist_enemy = np.where(dist_enemy > 1e8, 140.0, dist_enemy)
    tr = max(500.0 - st["step"], 1.0); boost = max(0.0, 1.0 - st["step"]/40.0)
    value_rest = pp * tr * (1.0 + boost)
    return np.stack([mine.astype(float), enemy.astype(float), neutral.astype(float),
        px/100.0, py/100.0, st["pr"]/3.0, np.log1p(np.maximum(ps, 0.0))/7.0, pp/5.0,
        porb.astype(float), np.hypot(px-CENTER, py-CENTER)/70.0,
        np.arctan2(py-CENTER, px-CENTER)/math.pi,
        np.minimum(rentab, 6.0)/3.0, dist_enemy/70.0, np.log1p(value_rest)/9.0], -1)

def _inbound(st):
    """Naves em voo (amigas/inimigas) convergindo p/ cada planeta. Espelha
    inbound_ships() do treino: frota mira o planeta se dot>0 e perp<r+3."""
    P = P_MAX
    friend = np.zeros(P); enemy = np.zeros(P)
    fx, fy, fang = st["fx"], st["fy"], st["fang"]
    fown, fsh = st["fown"], st["fsh"]
    if len(fx) == 0:
        return friend, enemy
    px, py, pr = st["px"], st["py"], st["pr"]
    fdx = np.cos(fang); fdy = np.sin(fang)
    dpx = px[None, :] - fx[:, None]; dpy = py[None, :] - fy[:, None]    # [F,P]
    dot = dpx*fdx[:, None] + dpy*fdy[:, None]
    perp = np.sqrt(np.maximum(dpx*dpx + dpy*dpy - dot*dot, 0.0))
    heading = (dot > 0.0) & (perp < pr[None, :] + 3.0)                  # [F,P]
    fs = fsh[:, None]
    friend = np.sum(np.where(heading & (fown[:, None] == 0), fs, 0.0), 0)
    enemy  = np.sum(np.where(heading & (fown[:, None] == 1), fs, 0.0), 0)
    return friend, enemy

def _features16(st, friend_in, enemy_in):
    feat = _features14(st)
    return np.concatenate([feat,
        (np.log1p(friend_in)/7.0)[:, None],
        (np.log1p(enemy_in)/7.0)[:, None]], -1)

def _pair_features(st):
    px, py = st["px"], st["py"]; ps, pp, po = st["ps"], st["pp"], st["po"]
    xi = px[:, None]; yi = py[:, None]; xj = px[None, :]; yj = py[None, :]
    dist = np.hypot(xi-xj, yi-yj); segc = _seg_dist_center(xi, yi, xj, yj)
    need = _ships_needed(ps[None, :], pp[None, :], po[None, :], dist)
    sun = (segc < SUN_R + SUN_BUF).astype(float)
    return np.stack([dist/70.0, np.log1p(need)/7.0, sun], -1)

def _globals(st):
    po, ps, pp, pv = st["po"], st["ps"], st["pp"], st["pv"]
    mine = (po == 0) & pv; enemy = (po == 1) & pv
    return np.array([st["step"]/500.0, st["omega"]*20.0,
        math.log1p(ps[mine].sum())/9.0, math.log1p(ps[enemy].sum())/9.0,
        pp[mine].sum()/30.0, pp[enemy].sum()/30.0])

# ---- transformer forward (usa _W global) ---------------------------------- #
def _layernorm(x, l, eps=1e-6):
    mu = x.mean(-1, keepdims=True); var = x.var(-1, keepdims=True)
    return (x - mu) / np.sqrt(var + eps) * _W[f"params/{l}/scale"] + _W[f"params/{l}/bias"]

def _mha(y, mask, pre, heads=4):
    P, d = y.shape; hd = d // heads
    Q = np.einsum('pd,dhf->phf', y, _W[f"params/{pre}/query/kernel"]) + _W[f"params/{pre}/query/bias"]
    K = np.einsum('pd,dhf->phf', y, _W[f"params/{pre}/key/kernel"])   + _W[f"params/{pre}/key/bias"]
    V = np.einsum('pd,dhf->phf', y, _W[f"params/{pre}/value/kernel"]) + _W[f"params/{pre}/value/bias"]
    s = np.einsum('qhf,khf->hqk', Q, K) / math.sqrt(hd)
    s = np.where(mask[None, None, :], s, -1e30)
    s = s - s.max(-1, keepdims=True); w = np.exp(s); w = w / w.sum(-1, keepdims=True)
    o = np.einsum('hqk,khf->qhf', w, V)
    return np.einsum('qhf,hfd->qd', o, _W[f"params/{pre}/out/kernel"]) + _W[f"params/{pre}/out/bias"]

def _forward_tf(feat, pm, glob, pair, heads=4, layers=2):
    P = feat.shape[0]; x = _lin(feat, "Dense_0")
    blocks = [("LayerNorm_0","LayerNorm_1","MultiHeadDotProductAttention_0","Dense_2","Dense_1"),
              ("LayerNorm_2","LayerNorm_3","MultiHeadDotProductAttention_1","Dense_4","Dense_3")]
    for (l1, l2, mh, fin, fout) in blocks[:layers]:
        x = x + _mha(_layernorm(x, l1), pm, mh, heads)
        x = x + _lin(_relu(_lin(_layernorm(x, l2), fin)), fout)
    m = pm[:, None].astype(np.float64); pmean = (x*m).sum(0) / max(m.sum(), 1.0)
    g = _relu(_lin(np.concatenate([pmean, glob]), "Dense_5")); g = _lin(g, "Dense_6")
    cat = np.concatenate([x, np.broadcast_to(g[None, :], (P, g.shape[0]))], -1)
    h = _lin(_relu(_lin(cat, "Dense_8")), "Dense_7")
    k = _lin(_relu(_lin(cat, "Dense_10")), "Dense_9")
    scores = (h @ k.T) / math.sqrt(h.shape[1])
    scores = scores + _lin(_relu(_lin(pair, "Dense_11")), "Dense_12")[..., 0]
    logits = np.concatenate([_lin(h, "Dense_13"), scores], -1)
    value = _lin(g, "Dense_14")[0]; frac = _lin(h, "Dense_15")
    return logits, frac, value

# ---- masks + swept + decode ----------------------------------------------- #
def _masks(st):
    po, px, py, pv = st["po"], st["px"], st["py"], st["pv"]
    mine = (po == 0) & pv; free = np.maximum(st["ps"] - GARRISON, 0.0)
    src = mine & (free >= 1.0)
    xi = px[:, None]; yi = py[:, None]; xj = px[None, :]; yj = py[None, :]
    dist = np.hypot(xi-xj, yi-yj); segc = _seg_dist_center(xi, yi, xj, yj)
    eye = np.eye(P_MAX, dtype=bool)
    tgt = (src[:, None] & pv[None, :] & ~eye & (dist <= MAX_DIST) & (segc >= SUN_R + SUN_BUF))
    return src, tgt, free

def _swept_pair_hit(ax, ay, bx, by, p0x, p0y, p1x, p1y, r):
    d0x, d0y = ax-p0x, ay-p0y; dvx = (bx-ax)-(p1x-p0x); dvy = (by-ay)-(p1y-p0y)
    aa = dvx*dvx + dvy*dvy; bb = 2.0*(d0x*dvx + d0y*dvy); cc = d0x*d0x + d0y*d0y - r*r
    if aa < 1e-12: return cc <= 0.0
    disc = bb*bb - 4.0*aa*cc
    if disc < 0.0: return False
    sq = math.sqrt(disc); t1 = (-bb-sq)/(2.0*aa); t2 = (-bb+sq)/(2.0*aa)
    return t2 >= 0.0 and t1 <= 1.0

def _will_hit(sx, sy, sr, tx, ty, tr, angle, ships, orbits, omega, max_ticks):
    sp = min(MAX_SPEED, float(_speed(np.array([ships]))[0]))
    ax = sx + math.cos(angle)*(sr+LAUNCH_CLEAR); ay = sy + math.sin(angle)*(sr+LAUNCH_CLEAR)
    stepx = math.cos(angle)*sp; stepy = math.sin(angle)*sp
    dx0, dy0 = tx-CENTER, ty-CENTER; px_prev, py_prev = tx, ty
    for t in range(1, int(max_ticks)+1):
        bx, by = ax+stepx, ay+stepy
        if orbits:
            a = omega*t; ca, sa = math.cos(a), math.sin(a)
            px_new = CENTER + dx0*ca - dy0*sa; py_new = CENTER + dx0*sa + dy0*ca
        else:
            px_new, py_new = tx, ty
        if _swept_pair_hit(ax, ay, bx, by, px_prev, py_prev, px_new, py_new, tr): return True
        if not (0.0 <= bx <= BOARD and 0.0 <= by <= BOARD): return False
        if _seg_dist_center_s(ax, ay, bx, by) < SUN_R: return False
        ax, ay, px_prev, py_prev = bx, by, px_new, py_new
    return False

def _decode(st, action, frac_action, free, friend_in=None):
    po, px, py, pr = st["po"], st["px"], st["py"], st["pr"]
    ps, pp = st["ps"], st["pp"]; porb, omega = st["porb"], st["omega"]
    theta = st.get("theta", 0.0); moves = []; planets = st["planets"]
    for i in range(P_MAX):
        ai = int(action[i])
        if ai == 0: continue
        j = ai - 1; fi = float(free[i])
        if fi < 1.0: continue
        frac = float(FRAC_BINS[int(frac_action[i])])
        tx, ty, tr = px[j], py[j], pr[j]; sx, sy, sr = px[i], py[i], pr[i]
        raw = max(min(frac*fi, fi), 0.0)
        # snap-to-need: ao atacar alvo capturavel, nunca enviar menos que o
        # necessario (corrige o "erra por 1"). Desconta frotas amigas ja a
        # caminho (coalizao) -> espelha o decode do treino v3.
        if po[j] != 0:                                   # nao-reforco (inimigo/neutro)
            dist0 = math.hypot(tx - sx, ty - sy)
            need = float(_ships_needed(np.array([ps[j]]), np.array([pp[j]]),
                                       np.array([po[j]]), np.array([dist0]))[0])
            fin_j = float(friend_in[j]) if friend_in is not None else 0.0
            need_eff = math.ceil(max(need - fin_j, 0.0))
            if need_eff > 0 and fi >= need_eff:
                raw = max(raw, need_eff)
        send = math.floor(raw)
        if send < 1: continue
        sp = float(_speed(np.array([max(send, 1.0)]))[0]); ax, ay = tx, ty
        for _ in range(6):
            eta = max(0.0, math.hypot(ax-sx, ay-sy) - (sr+0.1)) / sp
            if porb[j]:
                a = omega*eta; ca, sa = math.cos(a), math.sin(a)
                dx, dy = tx-CENTER, ty-CENTER
                ax = CENTER + dx*ca - dy*sa; ay = CENTER + dx*sa + dy*ca
            else:
                ax, ay = tx, ty
        angle = math.atan2(ay-sy, ax-sx)
        max_ticks = int(math.ceil(math.hypot(ax-sx, ay-sy)/sp)) + SWEPT_BUFFER
        if not _will_hit(sx, sy, sr, tx, ty, tr, angle, send, bool(porb[j]), omega, max_ticks):
            continue
        angle += theta
        moves.append([planets[i][0], angle, int(send)])
    return moves

# --------------------------------------------------------------------------- #
_NP_CACHE = [None]

def agent(obs, conf=None):
    me = int(obs.get("player", 0)) if hasattr(obs, "get") else int(getattr(obs, "player", 0))
    planets = obs["planets"] if hasattr(obs, "get") else obs.planets
    step = int(obs.get("step", 0)) if hasattr(obs, "get") else int(getattr(obs, "step", 0))
    if step == 0 or _NP_CACHE[0] is None:
        _NP_CACHE[0] = max(2, len({p[1] for p in planets if p[1] not in (-1, None)}))
    global _W
    _W = _W_2P if _NP_CACHE[0] == 2 else _W_4P
    theta = _theta(_NP_CACHE[0], me)
    st = _parse_obs(obs, me=me, theta=theta)
    fin, ein = _inbound(st)
    feat = _features16(st, fin, ein); pair = _pair_features(st); glob = _globals(st); pm = st["pv"]
    logits, frac_l, value = _forward_tf(feat, pm, glob, pair)
    src, tgt, free = _masks(st)
    tgt = tgt & ~st["is_comet"][None, :]
    full = np.concatenate([np.ones((P_MAX, 1), bool), tgt], -1)
    logits = np.where(full, logits, -1e9)
    action = np.where(src, np.argmax(logits, -1), 0)
    frac_action = np.argmax(frac_l, -1)
    return _decode(st, action, frac_action, free, fin)
